@startuml

class User {
  + fullName : string
}

class UnderAgedUser extends User {
  + studentCard : string
}

class AdultUser extends User {
  + idCard : string
}

class Book {
  + title : string
  + author : string
}

class BorrowingHistory {
  + borrowDate : date
  + returnDate : date
}

class Loan {
  + borrowDate : date
}

User "1" -- "0..4" Loan : currently borrows
User "1" -- "0..*" BorrowingHistory : has
Loan "0..*" -- "1" Book : includes
BorrowingHistory "0..*" -- "1" Book : includes

@enduml

